// Signals as process events: a listener catches its signal (the default action no longer
// happens), removing the last one stops catching it, and SIGKILL can't be caught. The same
// package under Node.js prints the same.
module.exports = function run() {
  try {
    process.on("SIGKILL", () => {});
  } catch (e) {
    console.log("SIGKILL", e.message, e.code, e.errno, e.syscall);
  }
  console.log("SIGKILL listeners", process.listenerCount("SIGKILL"));
  process.on("SIGUSR2", (...args) => {
    console.log("SIGUSR2", args[0], args[1] === require("os").constants.signals.SIGUSR2);
    const never = () => console.log("never");
    process.on("SIGUSR1", never);
    process.off("SIGUSR1", never);
    process.once("SIGTERM", (name) => {
      console.log("caught", name);
      setTimeout(() => console.log("shut down"), 20);
    });
    process.kill(process.pid, "SIGTERM");
  });
  process.kill(process.pid, "SIGUSR2");
  setTimeout(() => {}, 300);
};
